package dev.eugheist.ttmodern;
final class AwakenedBootsAudit {
 static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT awakened boots: "+label);}
 static float air(net.minecraft.world.entity.player.Player p){try{var m=net.minecraft.world.entity.player.Player.class.getDeclaredMethod("getFlyingSpeed");m.setAccessible(true);return (Float)m.invoke(p);}catch(ReflectiveOperationException e){throw new IllegalStateException(e);}}
 static void run(net.minecraft.server.MinecraftServer server){var level=server.overworld();var p=new net.neoforged.neoforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"BootsAudit"));p.setPos(-30.5,290,-30.5);p.setYRot(0);var pos=new net.minecraft.core.BlockPos(-30,289,-30);var old=level.getBlockState(pos);var stack=new net.minecraft.world.item.ItemStack(AwakenedBoots.ITEM.get());p.setItemSlot(net.minecraft.world.entity.EquipmentSlot.FEET,stack);AwakenedArmorStatus.set(p,true);p.getAbilities().flying=false;p.zza=1;p.setOnGround(true);p.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);p.fallDistance=9;
 try{level.setBlock(pos,net.minecraft.world.level.block.Blocks.DIRT.defaultBlockState(),2);AwakenedBoots.update(p);check(Math.abs(p.getDeltaMovement().z-.15)<1e-6&&p.fallDistance==0,"original ground acceleration and fall reset");check(level.getBlockState(pos).is(net.minecraft.world.level.block.Blocks.GRASS_BLOCK),"original negative coordinate truncation dirt conversion");check(p.getEffect(net.minecraft.world.effect.MobEffects.DIG_SPEED).getAmplifier()==1&&p.getEffect(net.minecraft.world.effect.MobEffects.DIG_SPEED).getDuration()==2,"haste II duration two");check(air(p)==.04f,"native air control");p.setSprinting(true);check(air(p)==.05f,"native sprint air control");p.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);p.getAbilities().flying=true;check(air(p)==p.getAbilities().getFlyingSpeed()*2,"original creative flight bypasses boots air control");AwakenedBoots.update(p);check(Math.abs(p.getDeltaMovement().z-.075)<1e-6,"original flying acceleration");p.setSprinting(false);p.getAbilities().flying=false;p.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);p.jumpFromGround();check(Math.abs(p.getDeltaMovement().y-.72)<1e-5,"real native jump plus .3");AwakenedArmorItem.toggle(stack);p.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);p.removeAllEffects();AwakenedBoots.update(p);check(p.getDeltaMovement().lengthSqr()==0&&!p.hasEffect(net.minecraft.world.effect.MobEffects.DIG_SPEED)&&air(p)==.02f,"individual disabled restores ordinary movement");var fall=new net.neoforged.neoforge.event.entity.living.LivingFallEvent(p,20,1);net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(fall);check(fall.getDistance()==0,"fall immunity even individually disabled");AwakenedArmorStatus.set(p,false);fall=new net.neoforged.neoforge.event.entity.living.LivingFallEvent(p,20,1);net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(fall);check(fall.getDistance()==0,"fall immunity even globally disabled");
 var recipe=dev.eugheist.tc4modern.InfusionItemRecipes.all().stream().filter(r->r.key().equals("ICHORCLOTH_BOOTS_GEM")).findFirst().orElseThrow();var parts=recipe.componentStacks();check(parts.size()==12&&parts.get(7).is(FocusResearch.item("arcane_bore"))&&parts.get(8).is(FocusResearch.item("lamp_growth"))&&parts.stream().noneMatch(net.minecraft.world.item.ItemStack::isEmpty),"original twelve resolved ingredients");var input=new net.minecraft.world.item.ItemStack(KamiArmor.ITEMS.get(3).get());check(dev.eugheist.tc4modern.InfusionItemRecipes.match(parts,input,java.util.Set.of(recipe.research()))==recipe&&dev.eugheist.tc4modern.InfusionItemRecipes.match(parts,input,java.util.Set.of())==null,"native infusion and research lock");var r=thaumcraft.api.research.ResearchCategories.getResearch(recipe.research());check(r.displayColumn==15&&r.displayRow==10&&r.getPages().length==2,"original research position and pages");System.out.println("TT AWAKENED BOOTS AUDIT: ALL PASS (native jump/air control,ground/flight acceleration,toggles,haste,fall immunity,negative dirt conversion,12part native infusion/research)");
 }finally{level.setBlock(pos,old,2);p.removeAllEffects();p.discard();}
 }
}
